package com.jobhub.integration;
import com.jobhub.integration.support.*;import org.junit.jupiter.api.Test;import org.springframework.http.*;import static org.assertj.core.api.Assertions.assertThat;
class ResumeVersionIntegrationTest extends AbstractIntegrationTest {
 @Test void AT33_comparesOnlyUserProvidedLinesWithoutMutation(){String left=create("基础版","Java\nSpring Boot\n旧项目描述"),right=create("岗位版","Java\nSpring Boot\n新项目描述");String compared=restTemplate.getForEntity(url("/resume-versions/compare?leftId="+left+"&rightId="+right),String.class).getBody();assertThat(compared).contains("UNCHANGED","REMOVED","旧项目描述","ADDED","新项目描述");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resume_version",Integer.class)).isEqualTo(2);ResponseEntity<String> same=restTemplate.getForEntity(url("/resume-versions/compare?leftId="+left+"&rightId="+left),String.class);assertThat(same.getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM resume_version",Integer.class)).isEqualTo(2);}
 private String create(String name,String content){ResponseEntity<String> r=restTemplate.exchange(url("/resume-versions"),HttpMethod.POST,TestFixtures.httpWithHeaders("{\"name\":\""+name+"\",\"content\":\""+content.replace("\n","\\n")+"\"}","Idempotency-Key",TestFixtures.newKey()),String.class);assertThat(r.getStatusCode()).isEqualTo(HttpStatus.CREATED);return JsonProbe.str(r.getBody(),"id");}
}
